package com.sopaan.rules;

import com.fasterxml.jackson.databind.JsonNode;
import com.sopaan.common.CanonicalJson;
import org.junit.jupiter.api.Test;

import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

/** The Java server must agree with the shared vectors generated by tools/build-packs.mjs. */
class RuleParityTest {
    @Test
    void sharedGoldenVectorsMatch() throws Exception {
        Path path = Path.of("../packs/vectors/eligibility.json");
        if (!Files.exists(path)) path = Path.of("packs/vectors/eligibility.json");
        assertTrue(Files.exists(path), "shared eligibility vectors are missing; run tools/build-packs.mjs");
        JsonNode vectors = CanonicalJson.parse(Files.readString(path));
        List<String> failures = new ArrayList<>();

        for (JsonNode test : vectors.path("cases")) {
            JsonNode criteria = test.path("criteria");
            Map<String, Object> profile = toMap(test.path("profile"));
            JsonLogic3v.Outcome outcome = JsonLogic3v.evaluate(criteria, profile);
            String expected = test.path("expect").asText();
            String actual = outcome.value();
            if (!matches(expected, outcome)) {
                failures.add(test.path("scheme_id").asText() + " expected " + expected + " but was "
                        + actual + (outcome.failing() == null ? "" : ":" + outcome.failing())
                        + (outcome.missing().isEmpty() ? "" : " missing=" + outcome.missing()));
            }
        }

        assertTrue(vectors.path("cases").size() >= 30, "expected the full vector set");
        assertEquals(List.of(), failures, String.join("\n", failures));
    }

    @Test
    void unknownBeatsAnyAndFalseBeatsUnknownInAll() throws Exception {
        JsonNode criteria = CanonicalJson.parse("""
                {"all":[
                  {"id":"c1","logic":{"<=":[{"var":"income"},100000]},"needs":["income"]},
                  {"id":"c2","logic":{">=":[{"var":"marks"},50]},"needs":["marks"]}
                ]}
                """);
        JsonLogic3v.Outcome unknown = JsonLogic3v.evaluate(criteria, Map.of("income", 90000));
        assertEquals("UNKNOWN", unknown.value());
        assertEquals(List.of("marks"), unknown.missing());

        JsonLogic3v.Outcome failed = JsonLogic3v.evaluate(criteria, Map.of("income", 200000));
        assertEquals("FALSE", failed.value());
        assertEquals("c1", failed.failing());
    }

    private boolean matches(String expected, JsonLogic3v.Outcome outcome) {
        if ("ELIGIBLE".equals(expected)) return "TRUE".equals(outcome.value());
        if (expected.startsWith("NOT:")) {
            return "FALSE".equals(outcome.value()) && expected.substring(4).equals(outcome.failing());
        }
        if (expected.startsWith("NEED:")) {
            if (!"UNKNOWN".equals(outcome.value())) return false;
            String fields = expected.substring(5).replaceAll("^\\[|\\]$", "");
            List<String> wanted = new ArrayList<>();
            for (String field : fields.split(",")) if (!field.trim().isEmpty()) wanted.add(field.trim());
            wanted.sort(String::compareTo);
            List<String> actual = new ArrayList<>(outcome.missing());
            actual.sort(String::compareTo);
            return wanted.equals(actual);
        }
        return false;
    }

    private Map<String, Object> toMap(JsonNode node) {
        Map<String, Object> values = new LinkedHashMap<>();
        node.fields().forEachRemaining(entry -> values.put(entry.getKey(), entry.getValue().isNumber()
                ? entry.getValue().numberValue()
                : entry.getValue().isBoolean() ? entry.getValue().booleanValue() : entry.getValue().asText()));
        return values;
    }
}
